for (const pkg of pkgs) {
  packageIsInstallable(pkg.rootDir, pkg.manifest, {
    ...opts,
    supportedArchitectures: opts?.supportedArchitectures ?? {
      os: ['current'],
      cpu: ['current'],
      libc: ['current'],
    },
  })

const pkgs = await findPackages(workspaceRoot, {
  ignore: [
    '**/node_modules/**',
    '**/bower_components/**',
  ],
  includeRoot: true,
