    diff: matches[3]?.slice(1, -1),
    exclude,
    excludeSelf,
    includeDependencies,
    includeDependents,
    namePattern: matches[1],
    parentDir: matches[2] && path.join(prefix, matches[2].slice(1, -1)),
  }
}

function isSelectorByLocation (rawSelector: string): boolean {
  if (rawSelector[0] !== '.') return false

